window.PETER_MCQ_BANK={"version":1,"sources":{"nephritic":{"title":"MSD Manual Professional — Overview Of Nephritic Syndrome","url":"https://www.msdmanuals.com/professional/nephrology/glomerular-disorders/overview-of-nephritic-syndrome","checked":"1 October 2026"},"iga":{"title":"MSD Manual Professional — Immunoglobulin A Nephropathy","url":"https://www.msdmanuals.com/professional/nephrology/glomerular-disorders/immunoglobulin-a-nephropathy","checked":"1 October 2026"},"mcd":{"title":"MSD Manual Professional — Minimal Change Disease","url":"https://www.msdmanuals.com/professional/nephrology/glomerular-disorders/minimal-change-disease","checked":"1 October 2026"},"fsgs":{"title":"MSD Manual Professional — Focal Segmental Glomerulosclerosis","url":"https://www.msdmanuals.com/professional/nephrology/glomerular-disorders/focal-segmental-glomerulosclerosis","checked":"1 October 2026"},"mem":{"title":"MSD Manual Professional — Membranous Nephropathy","url":"https://www.msdmanuals.com/professional/nephrology/glomerular-disorders/membranous-nephropathy","checked":"1 October 2026"},"rpgn":{"title":"MSD Manual Professional — Rapidly Progressive Glomerulonephritis Rpgn","url":"https://www.msdmanuals.com/professional/nephrology/glomerular-disorders/rapidly-progressive-glomerulonephritis-rpgn","checked":"1 October 2026"},"lupus":{"title":"MSD Manual Professional — Lupus Nephritis","url":"https://www.msdmanuals.com/professional/nephrology/glomerular-disorders/lupus-nephritis","checked":"1 October 2026"},"mpgn":{"title":"MSD Manual Professional — Membranoproliferative Glomerulonephritis","url":"https://www.msdmanuals.com/professional/nephrology/glomerular-disorders/membranoproliferative-glomerulonephritis","checked":"1 October 2026"},"nephrotic":{"title":"NIH NIDDK — Nephrotic Syndrome in Adults","url":"https://www.niddk.nih.gov/health-information/kidney-disease/nephrotic-syndrome-adults","checked":"1 October 2026"},"anemia":{"title":"NIH NIDDK — Anemia in Chronic Kidney Disease","url":"https://www.niddk.nih.gov/health-information/kidney-disease/anemia","checked":"1 October 2026"},"bone":{"title":"NIH NIDDK — Mineral & Bone Disorder in CKD","url":"https://www.niddk.nih.gov/health-information/kidney-disease/mineral-bone-disorder","checked":"1 October 2026"},"pkd":{"title":"NIH NIDDK — Autosomal Dominant Polycystic Kidney Disease","url":"https://www.niddk.nih.gov/health-information/kidney-disease/polycystic-kidney-disease/autosomal-dominant-pkd","checked":"1 October 2026"}},"questions":[{"id":"renal-001","revision":1,"system":"renal-system","topic":"glomerular-disease--nephrotic-syndromes","topicTitle":"Nephrotic Syndromes","stem":"A 35-year-old has generalised oedema, urine protein 6 g/day and serum albumin 20 g/L. Which syndrome best describes this combination?","options":[{"text":"Isolated microscopic haematuria","why":"Isolated haematuria means blood in the urine. It does not explain the combination of marked protein loss, low serum albumin and generalised oedema."},{"text":"Isolated renal glycosuria","why":"Renal glycosuria describes urinary glucose loss. The key abnormality here is heavy protein loss with hypoalbuminaemia, pointing to a nephrotic syndrome."},{"text":"Nephrotic syndrome","why":"Heavy protein loss with hypoalbuminaemia and oedema identifies this syndrome."},{"text":"Asymptomatic bacteriuria","why":"Bacteriuria concerns bacteria in urine. It does not account for 6 g/day of protein loss and the accompanying low albumin and oedema."},{"text":"Isolated tubular acidosis","why":"Tubular acidosis is an acid–base disorder. No acid–base findings are given, and it does not explain this characteristic protein-loss pattern."}],"answer":2,"takeaway":"Recognise the syndrome before deciding its underlying cause.","refs":["nephrotic"],"bookRefs":[],"difficulty":"core"},{"id":"renal-002","revision":1,"system":"renal-system","topic":"glomerular-disease--nephritic-syndromes","topicTitle":"Nephritic Syndromes","stem":"A patient develops dark urine, hypertension and rising creatinine. Which urine finding most strongly supports glomerular inflammation?","options":[{"text":"Red-cell casts","why":"Red-cell casts support a glomerular bleeding source in this clinical setting."},{"text":"Positive urine nitrites alone","why":"Nitrites support bacteriuria, but do not localise bleeding to the glomerulus. Red-cell casts are more informative in this nephritic presentation."},{"text":"Isolated glucose on dipstick","why":"Glycosuria concerns glucose handling rather than glomerular bleeding. It would not establish the cause of dark urine and rising creatinine."},{"text":"Calcium oxalate crystals alone","why":"Crystals can be found in urine without glomerulonephritis. They do not provide the evidence of glomerular bleeding that red-cell casts do."},{"text":"A few squamous epithelial cells","why":"Squamous epithelial cells commonly reflect contamination during collection. They do not explain hypertension, impaired kidney function and suspected glomerular haematuria."}],"answer":0,"takeaway":"Urine microscopy helps localise the source of haematuria.","refs":["nephritic"],"bookRefs":[],"difficulty":"core"},{"id":"renal-003","revision":1,"system":"renal-system","topic":"nephritic-syndromes--iga-nephropathy-berger-disease","topicTitle":"IgA Nephropathy (Berger Disease)","stem":"A 22-year-old has recurrent visible haematuria beginning during upper respiratory infections. A biopsy shows dominant mesangial IgA deposits. What is the most likely diagnosis?","options":[{"text":"Minimal-change disease","why":"Minimal-change disease is associated with foot-process effacement rather than dominant mesangial IgA deposits. The biopsy therefore favours a different diagnosis."},{"text":"Anti-GBM disease","why":"Anti-GBM disease characteristically produces linear IgG staining. Dominant mesangial IgA is a different immune-deposition pattern."},{"text":"Membranous nephropathy","why":"Membranous nephropathy features capillary-wall deposits rather than dominant mesangial IgA. The biopsy location and immunoglobulin type argue against it."},{"text":"Diabetic nephropathy","why":"Diabetic nephropathy is characterised by diabetic glomerular changes. Neither a diabetic history nor that biopsy pattern is provided here."},{"text":"IgA nephropathy","why":"The timing and dominant mesangial IgA support IgA nephropathy."}],"answer":4,"takeaway":"Infection-associated haematuria plus the biopsy pattern is more informative than serum IgA alone.","refs":["iga"],"bookRefs":[{"book":"kumar11","pdfPages":[851],"printedPages":[810],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2185,2186],"printedPages":[2139,2140],"chapter":"308 — Glomerular diseases"}],"difficulty":"core"},{"id":"renal-004","revision":1,"system":"renal-system","topic":"nephritic-syndromes--poststreptococcal-glomerulonephritis","topicTitle":"Poststreptococcal Glomerulonephritis","stem":"A 9-year-old develops oedema and cola-coloured urine two weeks after streptococcal pharyngitis. C3 is low. What is the most likely diagnosis?","options":[{"text":"Minimal-change disease","why":"Minimal-change disease is typically nephrotic. It does not best explain this delayed poststreptococcal presentation with cola-coloured urine and low complement."},{"text":"Poststreptococcal glomerulonephritis","why":"Delayed nephritis after streptococcal infection with low complement is characteristic."},{"text":"Diabetic nephropathy","why":"Diabetic nephropathy requires an appropriate diabetic context. The short interval after infection and low C3 instead support an inflammatory glomerular process."},{"text":"Polycystic kidney disease","why":"Polycystic kidney disease is a cystic disorder. The stem provides no cystic findings and instead describes a characteristic postinfectious nephritic presentation."},{"text":"Membranous nephropathy","why":"Membranous nephropathy usually presents with nephrotic features. The infection-to-nephritis interval and low complement favour poststreptococcal glomerulonephritis here."}],"answer":1,"takeaway":"Distinguish delayed poststreptococcal nephritis from haematuria occurring during infection in IgA nephropathy.","refs":[],"bookRefs":[{"book":"harrison20","pdfPages":[2183],"printedPages":[2137],"chapter":"308 — Glomerular diseases"}],"difficulty":"core"},{"id":"renal-005","revision":1,"system":"renal-system","topic":"nephrotic-syndromes--minimal-change-disease","topicTitle":"Minimal-Change Disease","stem":"A child with nephrotic syndrome undergoes biopsy for an atypical course. Light microscopy is near normal, immune staining is negative and electron microscopy shows diffuse foot-process effacement. Which diagnosis fits best?","options":[{"text":"Membranous nephropathy","why":"Membranous nephropathy has subepithelial immune deposits. Negative immune staining and near-normal light microscopy favour minimal-change disease instead."},{"text":"Proliferative lupus nephritis","why":"Proliferative lupus nephritis should show proliferative injury and immune deposits. Those findings are absent from the biopsy described."},{"text":"Poststreptococcal glomerulonephritis","why":"Poststreptococcal glomerulonephritis produces inflammatory and immune-complex findings. The lack of those findings argues against it."},{"text":"Minimal-change disease","why":"This combination is typical of minimal-change disease."},{"text":"Renal amyloidosis","why":"Renal amyloidosis produces tissue deposits. Near-normal light microscopy with foot-process effacement and no deposits supports a different lesion."}],"answer":3,"takeaway":"Foot-process effacement must be interpreted with light microscopy and immune staining.","refs":["mcd"],"bookRefs":[{"book":"kumar11","pdfPages":[844,845],"printedPages":[803,804],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2188],"printedPages":[2142],"chapter":"308 — Glomerular diseases"}],"difficulty":"core"},{"id":"renal-006","revision":1,"system":"renal-system","topic":"nephrotic-syndromes--focal-segmental-glomerulosclerosis","topicTitle":"Focal Segmental Glomerulosclerosis","stem":"A kidney biopsy in an adult with proteinuria shows scarring in some glomeruli, affecting only part of each involved tuft. Which term describes this lesion?","options":[{"text":"Diffuse global glomerulosclerosis","why":"Diffuse means widespread involvement and global means the entire tuft. The biopsy explicitly describes only some glomeruli and part of each affected tuft."},{"text":"Focal segmental glomerulosclerosis","why":"Focal means some glomeruli; segmental means part of an affected tuft."},{"text":"Minimal-change disease","why":"Minimal-change disease does not describe established segmental scarring. The distribution of the scars is the decisive finding here."},{"text":"Membranous nephropathy","why":"Membranous nephropathy is characterised by capillary-wall immune deposits. The stem describes a scarring pattern rather than that deposit pattern."},{"text":"Diffuse proliferative glomerulonephritis","why":"Proliferative glomerulonephritis describes cellular proliferation. The lesion in this question is sclerosis, distributed focally and segmentally."}],"answer":1,"takeaway":"FSGS is a histological pattern; its cause still needs evaluation.","refs":["fsgs"],"bookRefs":[],"difficulty":"core"},{"id":"renal-007","revision":1,"system":"renal-system","topic":"nephrotic-syndromes--membranous-nephropathy","topicTitle":"Membranous Nephropathy","stem":"A 54-year-old with nephrotic syndrome has subepithelial immune deposits and thickened glomerular capillary walls. Serum anti-PLA2R is positive. Which diagnosis is most likely?","options":[{"text":"IgA nephropathy","why":"IgA nephropathy is associated with dominant mesangial IgA. Subepithelial deposits and anti-PLA2R positivity instead favour membranous nephropathy."},{"text":"Anti-GBM disease","why":"Anti-GBM disease produces linear IgG staining. This is different from the subepithelial deposit pattern described."},{"text":"Minimal-change disease","why":"Minimal-change disease usually lacks immune deposits. The demonstrated deposits and anti-PLA2R result argue against it."},{"text":"ANCA-associated glomerulonephritis","why":"ANCA-associated glomerulonephritis is generally pauci-immune. Substantial subepithelial immune deposits point to a different process."},{"text":"Membranous nephropathy","why":"The deposits and anti-PLA2R result support membranous nephropathy."}],"answer":4,"takeaway":"Anti-PLA2R is a useful clue in membranous nephropathy.","refs":["mem"],"bookRefs":[],"difficulty":"core"},{"id":"renal-008","revision":1,"system":"renal-system","topic":"nephrotic-syndromes--diabetic-nephropathy","topicTitle":"Diabetic Nephropathy","stem":"A patient with longstanding diabetes and progressive albuminuria has nodular mesangial sclerosis on biopsy. Which named lesion is most characteristic?","options":[{"text":"Epithelial crescents","why":"Crescents indicate severe glomerular injury. They are not the named nodular mesangial lesion characteristic of diabetic glomerulosclerosis."},{"text":"Subepithelial humps","why":"Subepithelial humps are immune deposits, associated with postinfectious disease. They are different from the nodular mesangial sclerosis described."},{"text":"Kimmelstiel–Wilson nodules","why":"These nodules are characteristic of diabetic glomerulosclerosis."},{"text":"Mesangial IgA deposits","why":"Mesangial IgA deposits suggest IgA-mediated disease. They are not the characteristic nodules of diabetic glomerular injury."},{"text":"Congo-red-positive fibrils","why":"Congo-red-positive fibrils support amyloidosis. The named lesion asked for here is the characteristic diabetic mesangial nodule."}],"answer":2,"takeaway":"Diabetic glomerular injury includes mesangial expansion and basement-membrane thickening.","refs":[],"bookRefs":[{"book":"kumar11","pdfPages":[848],"printedPages":[807],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2190,2191],"printedPages":[2144,2145],"chapter":"308 — Glomerular diseases"}],"difficulty":"core"},{"id":"renal-009","revision":1,"system":"renal-system","topic":"nephritic-syndromes--goodpasture-s-syndrome","topicTitle":"Goodpasture’s Syndrome","stem":"A patient has haemoptysis, rapidly deteriorating kidney function and linear IgG staining along glomerular basement membranes. Which antibody is most relevant?","options":[{"text":"Anti-GBM antibody","why":"Pulmonary–renal disease with linear IgG suggests anti-GBM disease."},{"text":"Anti-PLA2R antibody","why":"Anti-PLA2R supports membranous nephropathy. It does not explain the characteristic linear IgG pattern in this pulmonary–renal presentation."},{"text":"Anti-mitochondrial antibody","why":"This antibody would not account for linear IgG along the GBM. The combination of lung haemorrhage and this biopsy pattern points to anti-GBM antibodies."},{"text":"Anti-centromere antibody","why":"This does not match the demonstrated basement-membrane antibody pattern. The biopsy provides the more specific clue to the relevant antibody."},{"text":"Anti-intrinsic-factor antibody","why":"This does not explain the pulmonary–renal syndrome or linear glomerular staining. Anti-GBM antibodies directly fit both the presentation and biopsy."}],"answer":0,"takeaway":"Linear IgG is the key biopsy clue to anti-GBM disease.","refs":["rpgn"],"bookRefs":[{"book":"kumar11","pdfPages":[852,853],"printedPages":[811,812],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2185],"printedPages":[2139],"chapter":"308 — Glomerular diseases"}],"difficulty":"core"},{"id":"renal-010","revision":1,"system":"renal-system","topic":"nephritic-syndromes--anca-antineutrophil-cytoplasmic-autoantibody-glomerulonephritis","topicTitle":"ANCA (Antineutrophil Cytoplasmic autoantibody) glomerulonephritis","stem":"A patient with a positive MPO-ANCA has necrotising crescentic glomerulonephritis. Immunofluorescence shows very little immunoglobulin deposition. How is this pattern described?","options":[{"text":"Linear immune deposition","why":"Linear staining means antibody binding along the basement membrane, typical of anti-GBM disease. Here there is very little immune deposition."},{"text":"Full-house immune deposition","why":"Full-house staining describes multiple immunoglobulins and complement, favouring lupus nephritis. That is the opposite of the sparse deposits described."},{"text":"Dominant mesangial IgA deposition","why":"Dominant mesangial IgA indicates an IgA-deposition pattern. The question instead specifies very little immunoglobulin and a positive MPO-ANCA."},{"text":"Pauci-immune","why":"Pauci-immune means few or absent immune deposits despite inflammation."},{"text":"Congo-red-positive deposition","why":"Congo-red-positive deposits support amyloid. They do not describe the sparse immune staining accompanying this necrotising crescentic lesion."}],"answer":3,"takeaway":"Severe glomerular inflammation can occur with few immune deposits.","refs":[],"bookRefs":[{"book":"kumar11","pdfPages":[853,854],"printedPages":[812,813],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2186],"printedPages":[2140],"chapter":"308 — Glomerular diseases"}],"difficulty":"core"},{"id":"renal-011","revision":1,"system":"renal-system","topic":"nephritic-syndromes--crescentic-rapidly-progressive-glomerulonephritis","topicTitle":"Crescentic (Rapidly Progressive) Glomerulonephritis","stem":"A patient’s creatinine rises from 100 to 310 micromol/L over two weeks, with red-cell casts. What is the most appropriate next approach?","options":[{"text":"Repeat kidney function in six months","why":"A six-month delay would leave rapidly progressive kidney injury uninvestigated. The creatinine change over two weeks and red-cell casts demand urgent assessment."},{"text":"Treat as uncomplicated cystitis without further investigation","why":"Uncomplicated cystitis does not account for red-cell casts and this rapid loss of kidney function. Treating it alone would miss suspected glomerular disease."},{"text":"Reassure because haematuria is intermittent","why":"The frequency of visible haematuria does not determine the severity of kidney injury. The rapid creatinine rise is an urgent finding regardless."},{"text":"Start long-term dialysis solely from this creatinine value","why":"A single creatinine value does not by itself determine dialysis need. The immediate priority includes urgent assessment of severity and the underlying cause."},{"text":"Urgent nephrology assessment, targeted serology and kidney biopsy when appropriate","why":"Rapid deterioration with nephritic sediment requires urgent investigation."}],"answer":4,"takeaway":"RPGN is urgent; identifying the cause directs treatment.","refs":[],"bookRefs":[{"book":"kumar11","pdfPages":[850,852,853],"printedPages":[809,811,812],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2180,2185,2186],"printedPages":[2134,2139,2140],"chapter":"308 — Glomerular diseases"}],"difficulty":"core"},{"id":"renal-012","revision":1,"system":"renal-system","topic":"other-syndromes--lupus-nephritis","topicTitle":"Lupus Nephritis","stem":"A patient with SLE develops proteinuria and red-cell casts. Which investigation most directly establishes the renal histological class and activity?","options":[{"text":"Serum ANA alone","why":"ANA supports an autoimmune context but does not show the kidney lesion. It cannot establish the renal histological class or activity."},{"text":"Renal ultrasound alone","why":"Ultrasound assesses renal structure, but cannot classify glomerular immune injury. Tissue assessment is required for the information asked for."},{"text":"Kidney biopsy","why":"Biopsy identifies class, activity and chronic damage."},{"text":"Urine culture alone","why":"Culture investigates urinary infection. It does not distinguish active lupus inflammation from chronic glomerular damage."},{"text":"Serum creatinine alone","why":"Creatinine reflects kidney function rather than the histological pattern. Different renal lesions can produce similar functional impairment."}],"answer":2,"takeaway":"Lupus renal treatment depends on the biopsy pattern and severity.","refs":["lupus"],"bookRefs":[{"book":"kumar11","pdfPages":[856],"printedPages":[815],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2184,2185],"printedPages":[2138,2139],"chapter":"308 — Glomerular diseases"}],"difficulty":"core"},{"id":"renal-013","revision":1,"system":"renal-system","topic":"other-syndromes--amyloidosis","topicTitle":"Amyloidosis","stem":"A patient with nephrotic syndrome has extracellular deposits that stain with Congo red and show green birefringence under polarised light. What is the best interpretation?","options":[{"text":"Definite AL amyloid without further tests","why":"Congo red identifies amyloid but does not establish AL as its type. Further typing is necessary before choosing precursor-directed treatment."},{"text":"Amyloid deposition, requiring further typing","why":"The stain supports amyloid, but does not establish the precursor type."},{"text":"Definite AA amyloid without further tests","why":"The stain does not identify AA specifically. An inflammatory cause cannot be concluded from Congo-red positivity alone."},{"text":"Anti-GBM disease","why":"Anti-GBM disease is associated with linear immune staining. Congo-red-positive extracellular deposits point to amyloid instead."},{"text":"Minimal-change disease","why":"Minimal-change disease involves podocyte foot-process changes, not these extracellular deposits. The stain is the key discriminator in this question."}],"answer":1,"takeaway":"Confirm amyloid, then type it; treatment depends on its precursor.","refs":[],"bookRefs":[{"book":"kumar11","pdfPages":[848],"printedPages":[807],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2191,2192],"printedPages":[2145,2146],"chapter":"308 — Glomerular diseases"}],"difficulty":"core"},{"id":"renal-014","revision":1,"system":"renal-system","topic":"other-syndromes--membranoproliferative-glomerulonephritis-mpgn","topicTitle":"Membranoproliferative Glomerulonephritis (MPGN)","stem":"A biopsy shows an MPGN pattern with strongly dominant C3 staining. Which mechanism deserves particular investigation?","options":[{"text":"Isolated podocyte change with no deposits","why":"An isolated minimal-change pattern does not explain dominant glomerular C3 deposition. The deposits require investigation of a complement-related mechanism."},{"text":"Antibodies solely against the GBM","why":"Anti-GBM disease typically has linear IgG staining. An MPGN pattern with dominant C3 suggests a different mechanism."},{"text":"Glucose-driven nodular sclerosis alone","why":"Diabetic nodular sclerosis does not explain dominant C3 deposits by itself. The staining directs the investigation beyond glucose-related injury."},{"text":"Complement dysregulation","why":"C3-dominant deposits direct attention to complement-mediated disease."},{"text":"Cyst expansion from polycystin dysfunction","why":"Polycystin dysfunction causes cystic disease. It does not explain the immune-staining pattern in this glomerular biopsy."}],"answer":3,"takeaway":"MPGN describes a pattern; immunofluorescence helps identify its mechanism.","refs":["mpgn"],"bookRefs":[{"book":"kumar11","pdfPages":[854,855],"printedPages":[813,814],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2187],"printedPages":[2141],"chapter":"308 — Glomerular diseases"}],"difficulty":"core"},{"id":"renal-015","revision":1,"system":"renal-system","topic":"renal-system--chronic-kidney-disease","topicTitle":"Chronic Kidney Disease","stem":"A clinically stable adult has an eGFR of 48 mL/min/1.73 m² on repeated tests over four months. Which conclusion is best supported?","options":[{"text":"Persistent reduced GFR meets a criterion for CKD","why":"The reduction has persisted beyond three months."},{"text":"CKD is excluded if creatinine is within the laboratory range","why":"A creatinine result within the laboratory range can conceal reduced GFR. The repeatedly reduced eGFR and duration are the relevant findings."},{"text":"CKD requires dialysis dependence","why":"Dialysis dependence represents only advanced disease. CKD can be diagnosed at earlier stages using persistent kidney abnormalities."},{"text":"A normal urine dipstick excludes CKD","why":"A negative dipstick does not override persistently reduced GFR. CKD does not require detectable dipstick protein in every patient."},{"text":"One must wait two years before considering CKD","why":"The chronicity threshold is around three months, not two years. Four months of persistent reduction is sufficient in this case."}],"answer":0,"takeaway":"Assess chronicity, eGFR and albuminuria together.","refs":[],"bookRefs":[{"book":"kumar11","pdfPages":[878,879],"printedPages":[837,838],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2157,2158],"printedPages":[2111,2112],"chapter":"305 — Chronic kidney disease"}],"difficulty":"core"},{"id":"renal-016","revision":1,"system":"renal-system","topic":"renal-system--chronic-kidney-disease","topicTitle":"Chronic Kidney Disease","stem":"An adult with advanced CKD has normocytic anaemia, adequate iron stores and no evidence of bleeding. Which mechanism most directly contributes?","options":[{"text":"Excess intrinsic-factor production","why":"Intrinsic factor concerns vitamin B12 absorption. It is not the renal signal that stimulates marrow red-cell production."},{"text":"Increased renal erythropoietin production","why":"Increasing erythropoietin would stimulate red-cell production. In CKD, inadequate production of this hormone contributes to the anaemia."},{"text":"Reduced renal erythropoietin production","why":"Reduced erythropoietin limits marrow red-cell production."},{"text":"Excess haemoglobin synthesis","why":"Excess haemoglobin synthesis would not explain reduced red-cell output. The relevant problem is inadequate stimulation of erythropoiesis."},{"text":"Isolated urinary glucose loss","why":"Urinary glucose loss does not explain the erythropoietin deficiency associated with advanced CKD. The stem directs attention to reduced marrow stimulation."}],"answer":2,"takeaway":"CKD anaemia is multifactorial; reduced erythropoietin is a major mechanism.","refs":["anemia"],"bookRefs":[],"difficulty":"core"},{"id":"renal-017","revision":1,"system":"renal-system","topic":"renal-system--chronic-kidney-disease","topicTitle":"Chronic Kidney Disease","stem":"A patient with advanced CKD has elevated phosphate and elevated parathyroid hormone. Which mechanism best explains the secondary hyperparathyroidism?","options":[{"text":"Excess active vitamin D production","why":"Active vitamin D production generally decreases in advanced CKD. Excess production is the wrong direction for the mechanism described."},{"text":"Primary autonomous parathyroid adenoma in every case","why":"A primary adenoma is not required to explain these findings. Secondary hyperparathyroidism is a response to the mineral disturbances of CKD."},{"text":"Increased renal phosphate clearance","why":"Advanced CKD tends to impair phosphate elimination. Increased clearance would not explain the elevated phosphate in the stem."},{"text":"Phosphate retention and reduced active vitamin D production","why":"These changes disturb calcium balance and stimulate PTH secretion."},{"text":"Excess calcitonin as the usual initiating defect","why":"Calcitonin excess is not the usual initiating defect in CKD mineral disease. Phosphate retention and reduced active vitamin D provide the relevant mechanism."}],"answer":3,"takeaway":"CKD mineral disease connects phosphate handling, vitamin D and PTH.","refs":["bone"],"bookRefs":[],"difficulty":"core"},{"id":"renal-018","revision":1,"system":"renal-system","topic":"renal-system--polycystic-kidney-disease","topicTitle":"Polycystic Kidney Disease","stem":"A 40-year-old has bilateral enlarged cystic kidneys and a parent with confirmed ADPKD. If the patient has a heterozygous pathogenic variant, what is the usual risk of passing it to each child?","options":[{"text":"50%","why":"A heterozygous autosomal dominant variant has a one-in-two transmission probability."},{"text":"0%","why":"A heterozygous affected parent can pass on the variant. An unaffected allele does not eliminate transmission of the affected one."},{"text":"25%","why":"The usual risk here is one in two, not one in four. Each child receives one of the parent’s two alleles."},{"text":"75%","why":"The stated heterozygous dominant inheritance gives a one-in-two probability. It does not produce a three-in-four transmission risk."},{"text":"100%","why":"A child may inherit the unaffected allele. Transmission is therefore possible but not inevitable in each pregnancy."}],"answer":0,"takeaway":"Inheritance risk is per pregnancy and does not predict severity.","refs":["pkd"],"bookRefs":[],"difficulty":"core"},{"id":"renal-019","revision":1,"system":"renal-system","topic":"nephritic-syndromes--goodpasture-s-syndrome","topicTitle":"Goodpasture’s Syndrome","stem":"A patient with confirmed anti-GBM disease and pulmonary haemorrhage is receiving specialist-directed plasma exchange and immunosuppression. What is the main purpose of plasma exchange?","options":[{"text":"Permanently stop antibody production","why":"Plasma exchange removes existing circulating antibodies rather than permanently stopping their production. Immunosuppression addresses ongoing antibody formation."},{"text":"Reverse established glomerular fibrosis","why":"Removing antibodies can limit ongoing injury, but does not reverse established fibrosis. Existing damage influences the chance of renal recovery."},{"text":"Replace all kidney filtration indefinitely","why":"Plasma exchange is being used for antibody removal. It does not replace all kidney functions or provide indefinite renal replacement."},{"text":"Stimulate new anti-GBM antibody production","why":"Anti-GBM antibodies cause the injury being treated. Stimulating their production would oppose, rather than explain, the purpose of plasma exchange."},{"text":"Remove circulating pathogenic antibodies","why":"Plasma exchange removes circulating antibodies."}],"answer":4,"takeaway":"Antibody removal and suppression of further production are complementary.","refs":[],"bookRefs":[{"book":"kumar11","pdfPages":[853],"printedPages":[812],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2185],"printedPages":[2139],"chapter":"308 — Glomerular diseases"}],"difficulty":"core"},{"id":"renal-020","revision":1,"system":"renal-system","topic":"nephrotic-syndromes--membranous-nephropathy","topicTitle":"Membranous Nephropathy","stem":"A patient with membranous nephropathy and severe nephrotic syndrome develops sudden flank pain and haematuria. Which complication should be particularly considered?","options":[{"text":"New polycystic kidney disease","why":"An inherited cystic disorder does not explain this sudden complication of established nephrotic syndrome. The acute symptoms warrant evaluation for thrombosis."},{"text":"Renal-vein thrombosis","why":"Nephrotic hypercoagulability increases venous thrombosis risk, including the renal vein."},{"text":"Isolated renal glycosuria","why":"Glycosuria does not explain acute flank pain and haematuria. Nephrotic hypercoagulability makes a vascular complication particularly important here."},{"text":"New minimal-change disease as the usual explanation","why":"A new glomerular diagnosis should not be assumed from these symptoms. In severe nephrotic syndrome, renal-vein thrombosis is a recognised complication."},{"text":"Resolution of nephrotic syndrome","why":"Sudden pain and haematuria are not evidence of remission. They suggest a complication requiring assessment, even if the original diagnosis is established."}],"answer":1,"takeaway":"Nephrotic syndrome carries thrombotic risk; new symptoms need assessment.","refs":[],"bookRefs":[{"book":"kumar11","pdfPages":[846,847],"printedPages":[805,806],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2190],"printedPages":[2144],"chapter":"308 — Glomerular diseases"}],"difficulty":"core"},{"id":"renal-021","revision":1,"system":"renal-system","topic":"nephrotic-syndromes--minimal-change-disease","topicTitle":"Minimal-Change Disease","difficulty":"challenging","stem":"A 31-year-old has persistent nephrotic syndrome despite an adequate specialist-supervised glucocorticoid course. The original biopsy contained only four glomeruli, with near-normal light microscopy and foot-process effacement. Which explanation most warrants reconsideration before accepting treatment-resistant minimal-change disease?","options":[{"text":"Membranous nephropathy established by foot-process effacement","why":"Foot-process effacement is not specific for membranous disease. That diagnosis requires evidence such as its characteristic immune deposits, which the stem does not supply."},{"text":"IgA nephropathy established by the absence of immune staining","why":"IgA nephropathy requires the relevant deposit pattern. Absent immune staining cannot establish an IgA-mediated lesion."},{"text":"Diabetic nephropathy established by heavy proteinuria","why":"Heavy proteinuria is a syndrome shared by several diseases. Without a diabetic context or characteristic tissue changes, it does not establish diabetic nephropathy."},{"text":"Focal segmental sclerosis missed by the small biopsy sample","why":"FSGS may be missed because affected glomeruli are not uniformly distributed. Steroid resistance and limited sampling make review of the original diagnosis important."},{"text":"Amyloidosis excluded solely by the patient’s age","why":"Age alone cannot exclude amyloid. More importantly, the limited biopsy and steroid resistance give a direct reason to reconsider a potentially missed focal lesion."}],"answer":3,"takeaway":"An apparently minimal-change biopsy can miss focal sclerosis; interpret histology alongside sampling and clinical response.","refs":[],"bookRefs":[{"book":"kumar11","pdfPages":[844,845],"printedPages":[803,804],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2188],"printedPages":[2142],"chapter":"308 — Glomerular diseases"},{"book":"kumar11","pdfPages":[845],"printedPages":[804],"chapter":"26 — Kidney and urinary tract disease"}]},{"id":"renal-022","revision":1,"system":"renal-system","topic":"nephrotic-syndromes--membranous-nephropathy","topicTitle":"Membranous Nephropathy","difficulty":"challenging","stem":"A 46-year-old with biopsy-confirmed membranous nephropathy has stable kidney function, controlled blood pressure and protein excretion falling from 3.0 to 1.5 g/day on supportive therapy. Anti-PLA2R titres are low. There are no thrombotic or other serious nephrotic complications. Which approach is most appropriate?","options":[{"text":"Start rituximab now to prevent future progression","why":"Rituximab is useful in selected higher-risk disease, but declining proteinuria and stable function support supportive care and monitoring before exposing this patient to immunosuppression."},{"text":"Continue supportive care and monitor proteinuria and kidney function","why":"The improving proteinuria and stable function support continued observation with supportive treatment. Immunosuppression is selected according to risk rather than biopsy positivity alone."},{"text":"Start glucocorticoid monotherapy to accelerate remission","why":"Glucocorticoids alone have not shown benefit as a routine membranous regimen. Improving disease does not justify adding an ineffective standalone treatment."},{"text":"Start cyclophosphamide with glucocorticoids despite the improving trend","why":"This regimen can be appropriate for higher-risk disease. The decision should follow the trajectory and risk, rather than applying intensive therapy to every biopsy-confirmed case."},{"text":"Begin a calcineurin inhibitor to normalise residual proteinuria","why":"Residual proteinuria does not automatically require immunosuppression. Falling protein excretion and stable function favour continued supportive care with reassessment."}],"answer":1,"takeaway":"Membranous nephropathy management follows risk and trajectory, not the diagnosis alone.","refs":[],"bookRefs":[{"book":"kumar11","pdfPages":[847],"printedPages":[806],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2190],"printedPages":[2144],"chapter":"308 — Glomerular diseases"},{"book":"kumar11","pdfPages":[847],"printedPages":[806],"chapter":"26 — Kidney and urinary tract disease"}]},{"id":"renal-023","revision":1,"system":"renal-system","topic":"other-syndromes--lupus-nephritis","topicTitle":"Lupus Nephritis","difficulty":"challenging","stem":"A patient with longstanding SLE has progressive CKD. Repeat biopsy shows more than 90% globally sclerosed glomeruli, extensive fibrosis and little active inflammation. There is no extrarenal flare. Why is escalating immunosuppression unlikely to restore kidney function?","options":[{"text":"The decline is principally due to ongoing reversible immune inflammation","why":"Active lesions may respond to immunosuppression, but this biopsy instead shows extensive sclerosis and little activity. Function alone does not establish the balance of activity and damage."},{"text":"The impairment is predominantly reversible isolated podocyte dysfunction","why":"Extensive global sclerosis and fibrosis demonstrate structural loss. That is different from a predominantly functional podocyte disorder with preserved glomerular architecture."},{"text":"A fall in eGFR primarily reflects a transient haemodynamic change","why":"The biopsy supplies a substantial chronic structural explanation. A transient haemodynamic mechanism alone would not account for more than 90% global glomerular sclerosis."},{"text":"The biopsy primarily reflects early membranous lupus without chronic injury","why":"Membranous lupus may cause substantial proteinuria, but the described advanced global sclerosis and fibrosis are direct evidence of chronic damage."},{"text":"The impairment predominantly reflects chronic irreversible scarring","why":"Advanced sclerosing lupus nephritis reflects extensive chronic damage. Treatment directed at active inflammation is unlikely to reverse established glomerular loss and fibrosis."}],"answer":4,"takeaway":"Distinguish activity from chronicity before assuming more immunosuppression will improve renal function.","refs":[],"bookRefs":[{"book":"kumar11","pdfPages":[856,857],"printedPages":[815,816],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2184,2185],"printedPages":[2138,2139],"chapter":"308 — Glomerular diseases"},{"book":"kumar11","pdfPages":[857],"printedPages":[816],"chapter":"26 — Kidney and urinary tract disease"},{"book":"kumar11","pdfPages":[856],"printedPages":[815],"chapter":"26 — Kidney and urinary tract disease"}]},{"id":"renal-024","revision":1,"system":"renal-system","topic":"nephritic-syndromes--iga-nephropathy-berger-disease","topicTitle":"IgA Nephropathy (Berger Disease)","difficulty":"challenging","stem":"Two adults have biopsy-confirmed IgA nephropathy. Patient A has episodic visible haematuria during colds, normal blood pressure, preserved eGFR and little proteinuria. Patient B has no visible haematuria but sustained proteinuria, hypertension and declining eGFR. Which interpretation best assesses progression risk?","options":[{"text":"Patient B has the more concerning risk profile despite less visible bleeding","why":"Persistent proteinuria, hypertension and impaired function are adverse prognostic features. The amount of visible bleeding alone is a poor substitute for those measures."},{"text":"Patient A is necessarily at higher risk because visible bleeding is more dramatic","why":"Visible haematuria can occur with otherwise favourable clinical features. Its dramatic appearance does not outweigh the sustained adverse markers described in patient B."},{"text":"Both have the same prognosis because the diagnostic label is identical","why":"IgA nephropathy has a variable course. Clinical and histological risk features distinguish patients who share the same diagnosis."},{"text":"Patient B is low risk because the urine never looks red","why":"Absence of visible blood does not exclude progressive injury. Patient B already has sustained proteinuria and deteriorating function."},{"text":"A single serum IgA concentration determines the ranking","why":"Serum IgA alone neither establishes the diagnosis nor determines prognosis. Longitudinal kidney function, proteinuria, blood pressure and histology are more informative."}],"answer":0,"takeaway":"Assess progression using persistent risk markers rather than how striking an episode appears.","refs":[],"bookRefs":[{"book":"kumar11","pdfPages":[851,852],"printedPages":[810,811],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2186],"printedPages":[2140],"chapter":"308 — Glomerular diseases"},{"book":"kumar11","pdfPages":[851],"printedPages":[810],"chapter":"26 — Kidney and urinary tract disease"}]},{"id":"renal-025","revision":1,"system":"renal-system","topic":"other-syndromes--membranoproliferative-glomerulonephritis-mpgn","topicTitle":"Membranoproliferative Glomerulonephritis (MPGN)","difficulty":"challenging","stem":"A 59-year-old has proteinuria, haematuria and low complement. Biopsy reports an MPGN pattern with immunoglobulin and complement deposits. Which next approach best uses this result?","options":[{"text":"Prioritise inherited complement testing and defer investigation for secondary immune complexes","why":"Complement investigations may be relevant, particularly in C3-dominant disease. Immunoglobulin-containing deposits make an acquired immune-complex cause important to investigate here."},{"text":"Begin treatment for primary idiopathic MPGN before assessing for secondary causes","why":"The pattern does not establish an idiopathic cause. An infection, autoimmune condition or monoclonal process could change the appropriate treatment."},{"text":"Investigate an underlying infection, autoimmune disease or monoclonal process","why":"MPGN is a pattern of injury rather than one cause. The deposit pattern should guide investigation for an underlying process that may require targeted treatment."},{"text":"Use the low complement concentration to classify the disease as lupus nephritis","why":"Low complement is supportive but not specific for lupus. The clinical assessment, serology and full biopsy pattern are needed before assigning that cause."},{"text":"Use the degree of proteinuria to choose immunosuppression without further aetiological tests","why":"Proteinuria contributes to severity assessment but does not identify the mechanism. Treating an underlying cause may be central to management."}],"answer":2,"takeaway":"Ask what is causing an MPGN pattern before choosing disease-specific treatment.","refs":[],"bookRefs":[{"book":"kumar11","pdfPages":[855],"printedPages":[814],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2187],"printedPages":[2141],"chapter":"308 — Glomerular diseases"},{"book":"kumar11","pdfPages":[854,855],"printedPages":[813,814],"chapter":"26 — Kidney and urinary tract disease"}]},{"id":"renal-026","revision":1,"system":"renal-system","topic":"other-syndromes--amyloidosis","topicTitle":"Amyloidosis","difficulty":"challenging","stem":"A 68-year-old with nephrotic syndrome has both a chronic inflammatory disorder and a small monoclonal protein. Kidney biopsy confirms amyloid with Congo-red staining. What is the most important next step before deciding between inflammation-directed and plasma-cell-directed treatment?","options":[{"text":"Diagnose AL amyloid solely from the monoclonal protein","why":"A monoclonal protein raises suspicion but does not itself type the tissue deposits. Selecting clone-directed treatment requires establishing the relevant amyloid type."},{"text":"Diagnose AA amyloid solely from the inflammatory history","why":"Inflammation makes AA plausible, but is not conclusive in this patient. The competing monoclonal finding makes direct typing particularly important."},{"text":"Use the degree of proteinuria alone to choose the amyloid type","why":"Heavy proteinuria can occur with different amyloid types. It describes renal involvement rather than identifying the precursor protein."},{"text":"Treat Congo-red positivity as a reason to give the same regimen to all patients","why":"Congo red establishes amyloid but not its type. AL and AA require different approaches to reducing precursor production."},{"text":"Establish the amyloid precursor type in the tissue","why":"The two background conditions suggest different possible precursors. Typing the deposits identifies the process that treatment needs to suppress."}],"answer":4,"takeaway":"Clinical associations guide suspicion; amyloid typing directs treatment.","refs":[],"bookRefs":[{"book":"kumar11","pdfPages":[848],"printedPages":[807],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2191,2192],"printedPages":[2145,2146],"chapter":"308 — Glomerular diseases"},{"book":"kumar11","pdfPages":[847,848],"printedPages":[806,807],"chapter":"26 — Kidney and urinary tract disease"}]},{"id":"renal-027","revision":1,"system":"renal-system","topic":"nephrotic-syndromes--diabetic-nephropathy","topicTitle":"Diabetic Nephropathy","difficulty":"challenging","stem":"A 29-year-old with type 1 diabetes develops new heavy proteinuria, red-cell casts and a rapid fall in kidney function. Recent retinal assessment found no diabetic retinopathy. Which conclusion best guides further assessment?","options":[{"text":"Attribute all findings to diabetic nephropathy without further evaluation","why":"Diabetes does not prevent another kidney disease. Assuming it explains every finding could delay recognition of a potentially treatable glomerulonephritis."},{"text":"Exclude diabetic nephropathy with certainty because retinopathy is absent","why":"Absent retinopathy raises suspicion but does not prove that diabetic renal injury is impossible. The whole presentation and appropriate investigations determine the cause."},{"text":"Investigate a possible non-diabetic renal process, including biopsy when appropriate","why":"Rapid functional decline and active urine sediment are atypical enough to investigate another process. Absent retinopathy in type 1 diabetes adds concern but is not definitive."},{"text":"Use the amount of proteinuria to distinguish diabetic from immune-mediated disease","why":"Proteinuria occurs in both diabetic and non-diabetic glomerular disease. Its quantity alone cannot resolve this differential."},{"text":"Wait for retinopathy before referring for renal assessment","why":"The kidney findings already require assessment. Waiting for eye disease would ignore the rapid deterioration and active sediment."}],"answer":2,"takeaway":"An atypical renal course in diabetes deserves investigation rather than automatic attribution.","refs":[],"bookRefs":[{"book":"harrison20","pdfPages":[2191],"printedPages":[2145],"chapter":"308 — Glomerular diseases"}]},{"id":"renal-028","revision":1,"system":"renal-system","topic":"nephritic-syndromes--goodpasture-s-syndrome","topicTitle":"Goodpasture’s Syndrome","difficulty":"challenging","stem":"A patient with confirmed anti-GBM disease and pulmonary haemorrhage is receiving plasma exchange. A colleague suggests stopping cyclophosphamide because the circulating antibodies are already being removed. Which response best explains the purpose of combined treatment?","options":[{"text":"Antibody removal does not suppress ongoing antibody production","why":"Plasma exchange removes circulating antibody, while cyclophosphamide suppresses further synthesis. The treatments address different parts of the disease process."},{"text":"Plasma exchange and cyclophosphamide both act only by filtering blood","why":"Cyclophosphamide does not function as a blood filter. Its immunosuppressive effect complements physical removal of existing circulating antibody."},{"text":"Cyclophosphamide is given to reverse established glomerular fibrosis","why":"Established fibrosis is not reversed by cyclophosphamide. The aim is to limit ongoing immune injury rather than rebuild already scarred glomeruli."},{"text":"Plasma exchange prevents all further immune activation by itself","why":"Removing circulating antibodies does not reliably stop their continued production. Suppression of the immune response remains a separate treatment goal."},{"text":"Cyclophosphamide is included solely to replace missing kidney hormones","why":"Kidney hormone replacement is not the reason for this drug. It targets the immune process responsible for continuing antibody production."}],"answer":0,"takeaway":"In anti-GBM disease, removing antibody and suppressing its production are complementary strategies.","refs":[],"bookRefs":[{"book":"kumar11","pdfPages":[853],"printedPages":[812],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2185],"printedPages":[2139],"chapter":"308 — Glomerular diseases"},{"book":"kumar11","pdfPages":[853],"printedPages":[812],"chapter":"26 — Kidney and urinary tract disease"}]},{"id":"renal-029","revision":1,"system":"renal-system","topic":"renal-system--chronic-kidney-disease","topicTitle":"Chronic Kidney Disease","difficulty":"challenging","stem":"A 52-year-old has an eGFR of 82 mL/min/1.73 m², but urine albumin:creatinine ratio remains elevated on repeated samples across four months. Which assessment principle is most appropriate?","options":[{"text":"Exclude kidney disease because eGFR is greater than 60","why":"An eGFR above 60 does not exclude other markers of kidney damage. The persistent urine abnormality still needs evaluation."},{"text":"Assess persistent albuminuria alongside eGFR when evaluating kidney disease and risk","why":"Persistent albuminuria can indicate kidney damage even with preserved filtration. Kidney assessment incorporates both eGFR and urine albumin, together with chronicity."},{"text":"Use serum creatinine alone because it replaces urine assessment","why":"Serum creatinine assesses a different aspect of renal function. It does not replace assessment of persistent albumin loss."},{"text":"Require nephrotic-range protein loss before recognising renal damage","why":"Kidney damage is not confined to nephrotic-range proteinuria. Lesser but persistent albuminuria can still carry clinical significance."},{"text":"Treat a preserved eGFR as proof that the urine findings are transient","why":"Filtration and albumin leakage need not change in parallel. Repeated abnormal samples over four months directly argue against assuming a transient finding."}],"answer":1,"takeaway":"Preserved filtration does not make persistent albuminuria irrelevant.","refs":[],"bookRefs":[{"book":"kumar11","pdfPages":[878,879],"printedPages":[837,838],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2157,2158],"printedPages":[2111,2112],"chapter":"305 — Chronic kidney disease"}]},{"id":"renal-030","revision":1,"system":"renal-system","topic":"nephritic-syndromes--anca-antineutrophil-cytoplasmic-autoantibody-glomerulonephritis","topicTitle":"ANCA (Antineutrophil Cytoplasmic autoantibody) glomerulonephritis","difficulty":"challenging","stem":"A patient has pulmonary haemorrhage, rapidly progressive glomerulonephritis and a positive MPO-ANCA. Biopsy unexpectedly shows strong linear IgG staining along the GBM. Which additional antibody test most directly investigates this discrepancy?","options":[{"text":"Anti-dsDNA antibodies","why":"Lupus can cause pulmonary–renal disease, but linear GBM staining is a more direct clue to anti-GBM disease than to a lupus immune-complex pattern."},{"text":"Anti-PLA2R antibodies","why":"This test supports membranous nephropathy, where the deposit pattern differs. It is not the most direct explanation for linear IgG in this rapidly progressive presentation."},{"text":"Anti-streptolysin O antibodies","why":"Evidence of preceding streptococcal infection can support postinfectious disease. It would not best explain linear rather than granular glomerular IgG."},{"text":"Anti-GBM antibodies","why":"ANCA and anti-GBM antibodies can coexist. Linear IgG is the key reason to assess for a second antibody-mediated mechanism rather than dismissing the biopsy."},{"text":"Serum cryoglobulins","why":"Cryoglobulinaemia can produce an immune-complex glomerulonephritis. The specific linear staining in this case directs attention to anti-GBM antibodies instead."}],"answer":3,"takeaway":"A positive ANCA does not exclude coexisting anti-GBM disease.","refs":[],"bookRefs":[{"book":"kumar11","pdfPages":[853],"printedPages":[812],"chapter":"26 — Kidney and urinary tract disease"},{"book":"harrison20","pdfPages":[2186],"printedPages":[2140],"chapter":"308 — Glomerular diseases"},{"book":"kumar11","pdfPages":[853],"printedPages":[812],"chapter":"26 — Kidney and urinary tract disease"}]}]};
